case class DocState(text: String, caret: Int)        // immutable memento
class Editor {
  private var state = DocState("", 0)
  private var history: List[DocState] = Nil            // persistent caretaker
  def save(): Unit = {
    history = state :: history
    if (history.size > 100) history = history.take(100)
  }
  def undo(): Unit = history match {
    case head :: tail => state = head; history = tail
    case Nil          => ()
  }
}
